"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis or file counts.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import tomllib
import re
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define minimal fallbacks
# to ensure this module can be tested in isolation if artifacts.py is missing
# or being implemented in parallel.
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback definitions for standalone testing if artifacts.py is not yet present
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_malformed_path(k):
                malformed[k] = v
            elif is_generated_path(k):
                generated[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if not is_generated_path(path) and not is_malformed_path(path):
                if any(path.endswith(s) for s in suffixes):
                    count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name:10s} : {g.status:8s} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename
    # Format: ```language filename.py\ncontent\n```
    # Or: ```filename.py\ncontent\n```
    # We look for blocks where the info string contains a .py extension or similar

    pattern = r"```(?:\w+)?\s+([^\n`]+?)\n(.*?)\n```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for filename, content in matches:
        # Clean up filename
        filename = filename.strip()
        if not filename:
            continue

        # Heuristic: If the filename doesn't look like a path, skip or try to infer
        # We accept paths ending in .py, .toml, .cfg, .txt, etc.
        if not any(filename.endswith(ext) for ext in ('.py', '.toml', '.cfg', '.txt', '.md', '.json', '.yaml', '.yml')):
            # Try to see if it's just a name like "main.py"
            if '.' not in filename:
                continue

        # Normalize path separators
        filename = filename.replace('\\', '/')

        # Avoid overwriting if duplicate paths found (last one wins or first? usually last)
        bundle[filename] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict-like
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        # Filter bundle to remove generated/malformed files
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files_count = len(authored_bundle)
        python_files_count = count_source_files(authored_bundle, suffixes=('.py',))

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run verification on the directory
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs in-place for os.walk
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]

                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                content = f.read()
                            authored[rel_path] = content
                        except Exception:
                            pass

        authored_files_count = len(authored)
        python_files_count = count_source_files(authored, suffixes=('.py',))

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(workdir, authored))

        # Gate 2: Build
        gates.append(self._gate_build(workdir, authored))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, authored))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, authored))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source,
            harness_version='3.0-execution'
        )

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files to analyze'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source,
            harness_version='3.0-execution'
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files found',
                duration_s=time.time() - start_time
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start_time
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='Syntax errors found: ' + '; '.join(errors[:5]),
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg)',
                duration_s=time.time() - start_time
            )

        # If pyproject.toml is present, validate it
        if found_metadata == 'pyproject.toml':
            content = authored['pyproject.toml']
            try:
                data = tomllib.loads(content)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib_validation',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start_time
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib_validation',
                    detail=f'pyproject.toml is malformed: {str(e)}',
                    duration_s=time.time() - start_time
                )

        # Try to install
        # Check if pip is available
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available',
                duration_s=time.time() - start_time
            )

        # Run pip install -e . --no-deps --no-build-isolation
        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start_time
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr[:500]}',
                    duration_s=duration,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start_time
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Error running pip install: {str(e)}',
                duration_s=time.time() - start_time
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Find non-test authored modules
        # Exclude test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]
        all_py_files = [p for p in authored if p.endswith('.py')]
        non_test_modules = [p for p in all_py_files if p not in test_files]

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found',
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = os.pathsep.join([workdir, src_dir])

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Try to import each module in a subprocess
        # We'll try to import them one by one or all together? 
        # Spec says: "Non-test authored modules must import in a subprocess"
        # If any fails with syntax/runtime error -> FAILED
        # If fails solely with ModuleNotFoundError for third-party -> SKIPPED

        # Let's try to import all of them in one go to save time, but we need to distinguish errors.
        # Better to try importing each module individually to isolate errors.

        import_errors = []
        module_not_found_errors = []

        for module_path in non_test_modules:
            # Convert path to module name
            # e.g., src/foo/bar.py -> foo.bar
            # e.g., foo/bar.py -> foo.bar
            rel_path = module_path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            module_name = rel_path.replace('/', '.').replace('\\', '.')
            if module_name.endswith('.py'):
                module_name = module_name[:-3]

            # Skip __init__.py as they are usually empty or just imports
            if module_name.endswith('.__init__'):
                continue

            try:
                # Run a subprocess to import the module
                code = f"import {module_name}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    # Check if it's purely a ModuleNotFoundError for a third-party package
                    # This is tricky. We assume if the error is ModuleNotFoundError and the module name
                    # is not one of our local modules, it's third-party.
                    # However, if our local module imports a third-party package, it will fail.
                    # Spec: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"

                    if 'ModuleNotFoundError' in stderr:
                        # Check if the missing module is one of our local modules
                        # If the error is about importing a local module, it's a failure.
                        # If it's about a third-party package, it's skipped.
                        # Heuristic: If the error mentions a module that is not in our authored files, it's third-party.
                        # But we need to be careful.

                        # Let's check if the error is about the module itself or a dependency.
                        # If the module itself is not found, it's a failure (path issue).
                        # If a dependency is not found, it's skipped.

                        # Simple heuristic: If the error string contains "No module named" and the name is not a prefix of any of our modules, it's third-party.
                        # This is imperfect. Let's assume if it's ModuleNotFoundError, we check if the missing module is in our authored list.

                        # Extract missing module name
                        match = re.search(r"No module named '([^']+)'", stderr)
                        if match:
                            missing_mod = match.group(1)
                            # Check if missing_mod is one of our modules (or a parent package)
                            is_local = False
                            for mod_path in non_test_modules:
                                mod_name = mod_path.replace('/', '.').replace('\\', '.')
                                if mod_name.endswith('.py'):
                                    mod_name = mod_name[:-3]
                                if mod_name == missing_mod or mod_name.startswith(missing_mod + '.') or missing_mod.startswith(mod_name + '.'):
                                    is_local = True
                                    break

                            if not is_local:
                                module_not_found_errors.append(f"{module_name}: {missing_mod}")
                                continue

                    import_errors.append(f"{module_name}: {stderr[:200]}")

            except subprocess.TimeoutExpired:
                import_errors.append(f"{module_name}: Timeout")
            except Exception as e:
                import_errors.append(f"{module_name}: {str(e)}")

        duration = time.time() - start_time

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Import errors: ' + '; '.join(import_errors[:5]),
                duration_s=duration,
                evidence={'errors': import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail='Skipped due to missing third-party dependencies: ' + '; '.join(module_not_found_errors[:5]),
                duration_s=duration,
                evidence={'missing_deps': module_not_found_errors}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f"All {len(non_test_modules)} non-test modules imported successfully",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Discover test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail='No test files found',
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = os.pathsep.join([workdir, src_dir])

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Check if pytest is installed
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                capture_output=True,
                timeout=10
            )
            use_pytest = True
        except Exception:
            use_pytest = False

        if use_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start_time

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # Check if it's a third-party package
                        # Simple heuristic: if the error is about a package not in our authored files
                        # We'll assume if pytest fails with ModuleNotFoundError, it might be skipped
                        # But pytest might fail for other reasons.
                        # Let's check if the error is specifically about missing imports.
                        if 'No module named' in result.stderr or 'No module named' in result.stdout:
                            return GateResult(
                                name='tests',
                                status=SKIPPED,
                                method='pytest',
                                detail='Tests skipped due to missing dependencies',
                                duration_s=duration,
                                evidence={'stderr': result.stderr[:500]}
                            )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail='Tests failed',
                        duration_s=duration,
                        evidence={'stderr': result.stderr[:500], 'stdout': result.stdout[:500]}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out',
                    duration_s=time.time() - start_time
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Error running pytest: {str(e)}',
                    duration_s=time.time() - start_time
                )
        else:
            # Stdlib fallback
            # Run a subprocess that imports each test file and collects/executes tests
            # This is complex. We'll write a small script to run in subprocess.

            script = """
import sys
